+++ /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-cfg-none-t0m9bief/automation/ElementUITest/ElementUITestUITests/BookClubNotificationsUITests.swift
@@ -0,0 +1,22 @@
+import XCTest
+
+final class BookClubNotificationsUITests: XCTestCase {
+    func testOpenBookClubNotifications() {
+        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
+        app.activate()
+
+        let bookClub = app.staticTexts["Book Club"].firstMatch
+        XCTAssertTrue(bookClub.waitForExistence(timeout: 10))
+        bookClub.press(forDuration: 1.2)
+
+        let notifications = app.buttons["Notifications"].firstMatch
+        if notifications.waitForExistence(timeout: 5) {
+            notifications.tap()
+            return
+        }
+
+        let notificationSettings = app.buttons["Notification settings"].firstMatch
+        XCTAssertTrue(notificationSettings.waitForExistence(timeout: 5))
+        notificationSettings.tap()
+    }
+}

